// src/utils/rpc/isChromeExtension.ts
function isChromeExtension() {
  return typeof window !== "undefined" && window.location?.protocol === "chrome-extension:";
}

// src/utils/rpc/fetchFromApi.ts
async function fetchFromApi(clientUrl, clientKey, payload, requestOptions) {
  const hostname = window?.location?.hostname || "unknown";
  const uri = isChromeExtension() ? `chrome-extension://${hostname}` : hostname;
  const fetchResponse = await fetch(clientUrl, {
    ...requestOptions,
    method: "POST",
    headers: {
      "Content-Type": "application/json",
      Authorization: `Bearer ${clientKey}`,
      "X-AppInfo": `platform=web;version=${"1.0.16"};uri=${uri}`
    },
    body: JSON.stringify({
      ...payload,
      jsonrpc: "2.0",
      id: payload?.id ?? uuidv4()
    })
  });
  if (!fetchResponse.ok) {
    const errorResponse = await fetchResponse.json();
    throw new ResponseError(
      errorResponse,
      void 0,
      void 0,
      fetchResponse.status
    );
  }
  const jsonResponse = await fetchResponse.json();
  if ("error" in jsonResponse) {
    const errorResponse = jsonResponse;
    throw new EIP1193ProviderRpcError(
      errorResponse.error.code,
      errorResponse.error.message
    );
  }
  return jsonResponse;
}

// src/utils/rpc/isCircleUrl.ts
function isCircleUrl(url) {
  try {
    const parsedUrl = new URL(url);
    const allowedHosts = [
      "modular-sdk.circle.com",
      "modular-sdk-staging.circle.com"
    ];
    return allowedHosts.includes(parsedUrl.host);
  } catch {
    return false;
  }
}

// src/utils/rpc/validateClientUrl.ts
function validateClientUrl(clientUrl) {
  try {
    const url = new URL(clientUrl);
    const urlPattern = /^(https?:\/\/)([\da-zA-Z.-]+)(:[\d]{1,5})?([/\w .-]*)*(\?[^\s]*)?$/;
    if (!urlPattern.test(clientUrl)) {
      return false;
    }
    return url.protocol === "http:" || url.protocol === "https:";
  } catch {
    return false;
  }
}

// src/utils/rpc/webAuthnHelpers.ts
function adaptCredentialCreationOptions(options) {
  if (isChromeExtension()) {
    const { rp, ...restOptions } = options;
    const { id: _, ...rpWithoutId } = rp;
    return {
      ...restOptions,
      rp: rpWithoutId
    };
  }
  return options;
}
function adaptCredentialRequestOptions(options) {
  if (isChromeExtension()) {
    const { rpId: _, ...rest } = options;
    return rest;
  }
  return options;
}

// src/utils/signature/toReplaySafeHash.ts
import {
  concatHex,
  encodeAbiParameters as encodeAbiParameters5,
  encodePacked as encodePacked2,
  keccak256 as keccak2563,
  pad as pad3
} from "viem";
function toReplaySafeHash({
  address,
  chainId,
  hash
}) {
  const { name, version, domainSeparatorType, moduleType } = REPLAY_SAFE_HASH_V1;
  const domainSeparatorTypeHash = keccak2563(
    encodePacked2(["string"], [domainSeparatorType])
  );
  const moduleNameHash = keccak2563(encodePacked2(["string"], [name]));
  const moduleVersionHash = keccak2563(encodePacked2(["string"], [version]));
  const moduleTypeHash = keccak2563(encodePacked2(["string"], [moduleType]));
  const domainSeparator = keccak2563(
    encodeAbiParameters5(
      [
        { type: "bytes32" },
        { type: "bytes32" },
        { type: "bytes32" },
        { type: "uint256" },
        { type: "address" },
        { type: "bytes32" }
      ],
      [
        domainSeparatorTypeHash,
        moduleNameHash,
        moduleVersionHash,
        BigInt(chainId),
        CIRCLE_WEIGHTED_WEB_AUTHN_MULTISIG_PLUGIN.address,
        pad3(address, { dir: "right" })
      ]
    )
  );
  const structHash = keccak2563(
    encodeAbiParameters5(
      [{ type: "bytes32" }, { type: "bytes32" }],
      [moduleTypeHash, hash]
    )
  );
  return keccak2563(concatHex([EIP712_PREFIX, domainSeparator, structHash]));
}

// src/utils/signature/toWebAuthnSignature.ts
import { encodeAbiParameters as encodeAbiParameters6, stringToHex } from "viem";
import {
  parseSignature as parseP256Signature
} from "webauthn-p256";
function toWebAuthnSignature({
  webauthn,
  signature
}) {
  const { r, s } = parseP256Signature(signature);
  return encodeAbiParameters6(AUTHENTICATOR_DATA, [
    {
      webAuthnData: {
        authenticatorData: webauthn.authenticatorData,
        clientDataJSON: stringToHex(webauthn.clientDataJSON),
        challengeIndex: BigInt(webauthn.challengeIndex),
        typeIndex: BigInt(webauthn.typeIndex),
        requireUserVerification: webauthn.userVerificationRequired
      },
      r,
      s
    }
  ]);
}

// src/utils/signature/wrapSignature.ts
import { encodePacked as encodePacked3, size } from "viem";
function wrapSignature({
  sender,
  signature,
  hasUserOpGas
}) {
  const sigType = hasUserOpGas ? 34 : 2;
  return encodePacked3(
    ["bytes32", "uint256", "uint8", "uint256", "bytes"],
    [sender, 65n, sigType, BigInt(size(signature)), signature]
  );
}

// src/utils/signature/wrapEoaSignature.ts
import { encodePacked as encodePacked4, parseSignature } from "viem";
function wrapEoaSignature({
  signature,
  hasUserOpGas
}) {
  const { r, s, v } = parseSignature(signature);
  if (typeof v !== "undefined") {
    const signType = hasUserOpGas ? Number(v + 32n) : Number(v);
    return encodePacked4(["bytes32", "bytes32", "uint8"], [r, s, signType]);
  }
  throw new Error("signature is invalid");
}

